window.roroShowError=function(inputId,message="",show=!0){let inputWrapper=roroGetWrapper(inputId);if(!inputWrapper.length)return;let error=inputWrapper.find(".roro-input-error-container"),errorMessage=error.find(".roro-input-error-message");!error.length||!errorMessage.length||(errorMessage.text(message),error.toggle(show),manageBorderError(inputWrapper.find(".roro-border-error"),show))},window.manageBorderError=function(elt,show=null){show!==null&&elt.data("show",show),elt.data("show")?(elt.removeClass(elt.data("class")),elt.addClass(elt.data("class")),elt.data("show",!1)):(elt.removeClass(elt.data("class")),elt.addClass("roro-border-error"),elt.data("show",!0))},window.normalizeInputName=function(name){return name.split(".").reduce((acc,part,i)=>i===0?part:`${acc}[${part}]`,"")},window.roroGetWrapper=function(inputId){let input=$(`#${inputId}`),wrapper=$(`#roro-wrapper-${inputId}`);return input.hasClass("roro-input-radio")&&(wrapper=input.closest(".roro-wrapper-radio-container")),wrapper};
